fn merge(a: { ...r }, b: { ...s }): { ...r, ...s }
  where r disjoint s = { ...a, ...b };
fn wrap(a: { ...r }, b: { ...s }): { inner: { ...r, ...s } }
  = { inner: merge(a, b) };
fn apply0(f: (a, b) -> { inner: { x: Int, y: Int } }): Int = 0;
fn main(): Int = apply0(fn(p: { x: Int }, q: { y: Int }) => wrap(p, q));
